def backfill_partners(apps, schema_editor):
    """Tạo đối tác từ tổ GC (năng lực) + vendor_name phiếu cũ, gắn FK partner."""
    WorkCenter = apps.get_model('san_xuat', 'SxWorkCenter')
    Partner = apps.get_model('san_xuat', 'GcPartner')
    Order = apps.get_model('san_xuat', 'SxSubcontractOrder')

    by_name = {}
    used_codes = set()

    def _code(base):
        base = (base or 'GC').strip().upper()[:34] or 'GC'
        code, n = base, 1
        while code in used_codes or Partner.objects.filter(code=code).exists():
            n += 1
            code = f'{base}-{n}'
        used_codes.add(code)
        return code

    for wc in WorkCenter.objects.filter(is_demo=False, is_subcontract=True).order_by('pk'):
        name = (wc.name or '').strip()
        if not name or name.casefold() in by_name:
            continue
        by_name[name.casefold()] = Partner.objects.create(
            code=_code(wc.code or 'GC'), name=name, work_center=wc, is_active=wc.is_active,
        )

    names = (
        Order.objects.filter(partner__isnull=True).exclude(vendor_name='')
        .values_list('vendor_name', flat=True).distinct()
    )
    for raw in names:
        name = (raw or '').strip()
        if not name:
            continue
        key = name.casefold()
        if key not in by_name:
            by_name[key] = Partner.objects.create(code=_code(f'GC{len(by_name) + 1:03d}'), name=name)
        Order.objects.filter(partner__isnull=True, vendor_name=raw).update(partner=by_name[key])


